package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class JsonParserSequence_nextToken_TriageGen1Test {

    /**
     * Since the constructor and switchToNext are protected, 
     * we create a Testable subclass to gain access to them for testing.
     */
    private static class TestableJsonParserSequence extends JsonParserSequence {
        private boolean switchToNextResult = false;

        protected TestableJsonParserSequence(JsonParser[] parsers) {
            super(parsers);
        }

        public void setSwitchToNextResult(boolean result) {
            this.switchToNextResult = result;
        }

        @Override
        protected boolean switchToNext() {
            return switchToNextResult;
        }

        // Helper to manipulate the private _suppressNextToken if possible, 
        // but since we can't access it directly, we rely on the logic flow.
        // However, the provided code snippet shows _suppressNextToken is a field.
        // In a real scenario, we'd use reflection if it's not accessible.
        public void setSuppressNextToken(boolean suppress) throws Exception {
            java.lang.reflect.Field field = JsonParserSequence.class.getDeclaredField("_suppressNextToken");
            field.setAccessible(true);
            field.set(this, suppress);
        }
    }

    @Test
    public void testNextToken_DelegateNull() throws IOException {
        // To test delegate == null, we need to bypass the constructor or use reflection
        // because the constructor takes JsonParser[]. If array is empty, delegate might be null?
        // Actually, in Jackson, delegate is usually the first element.
        // Let's try to simulate via reflection if the constructor doesn't allow null delegate.

        JsonParserSequence sequence = mock(JsonParserSequence.class);
        // Since we can't easily instantiate a class with a null delegate via protected constructor 
        // without knowing the internal implementation of the constructor, 
        // we assume a scenario where the field 'delegate' is null.

        // Using a mock to simulate the behavior of a class where delegate is null
        // but since we are testing the real method, we must use the real class.
        // We'll use reflection to set delegate to null.
        TestableJsonParserSequence sequenceWithNull = new TestableJsonParserSequence(new JsonParser[0]);
        java.lang.reflect.Field delegateField = JsonParserSequence.class.getDeclaredField("delegate");
        delegateField.setAccessible(true);
        delegateField.set(sequenceWithNull, null);

        assertNull(sequenceWithNull.nextToken());
    }

    @Test
    public void testNextToken_SuppressNextTokenIsTrue() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.currentToken()).thenReturn(JsonToken.START_OBJECT);

        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setSuppressNextToken(true);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        verify(mockParser, times(1)).currentToken();

        // Verify _suppressNextToken is reset to false
        java.lang.reflect.Field suppressField = JsonParserSequence.class.getDeclaredField("_suppressNextToken");
        suppressField.setAccessible(true);
        assertEquals(false, suppressField.get(sequence));
    }

    @Test
    public void testNextToken_NormalFlow_NoSwitch() throws IOException {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setSwitchToNextResult(false);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(mockParser, times(1)).nextToken();
    }

    @Test
    public void testNextToken_WithSwitchToNext_HasCurrentToken() throws IOException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.hasCurrentToken()).thenReturn(true);
        when(parser2.currentToken()).thenReturn(JsonToken.FIELD_NAME);

        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});
        sequence.setSwitchToNextResult(true);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(parser1).nextToken();
        verify(parser2).hasCurrentToken();
        verify(parser2).currentToken();
    }

    @Test
    public void testNextToken_WithSwitchToNext_NoHasCurrentToken_CallsNextToken() throws IOException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.hasCurrentToken()).thenReturn(false);
        when(parser2.nextToken()).thenReturn(JsonToken.END_OBJECT);

        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});
        sequence.setSwitchToNextResult(true);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.END_OBJECT, result);
        verify(parser1).nextToken();
        verify(parser2).hasCurrentToken();
        verify(parser2).nextToken();
    }

    @Test
    public void testNextToken_LoopingSwitchToNext() throws IOException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);
        JsonParser parser3 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);

        // First switch: parser2 has current
        when(parser2.hasCurrentToken()).thenReturn(true);
        when(parser2.currentToken()).thenReturn(JsonToken.FIELD_NAME);

        // Second switch: parser3 has no current, call nextToken
        when(parser3.hasCurrentToken()).thenReturn(false);
        when(parser3.nextToken()).thenReturn(JsonToken.VALUE_STRING);

        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2, parser3});

        // We need to simulate multiple calls to switchToNext() returning true
        // This is tricky because our Testable class uses a simple boolean.
        // We can use a custom implementation for this specific test.
        SequenceWithMultipleSwitches sequenceMulti = new SequenceWithMultipleSwitches(new JsonParser[]{parser1, parser2, parser3});
        sequenceMulti.switchToNextSequence = new boolean[]{true, true, false};

        JsonToken result = sequenceMulti.nextToken();

        assertEquals(JsonToken.VALUE_STRING, result);
    }

    private static class SequenceWithMultipleSwitches extends TestableJsonParserSequence {
        boolean[] switchToNextSequence;
        int index = 0;

        SequenceWithMultipleSwitches(JsonParser[] parsers) {
            super(parsers);
        }

        @Override
        protected boolean switchToNext() {
            if (index < switchToNextSequence.length) {
                return switchToNextSequence[index++];
            }
            return false;
        }
    }
}
